definition.raw:
, which is defined as \cite{D09,Dat09}
\begin{equation}\label{eq:max-rel}
D_{\max}(\rho\Vert\sigma)\coloneqq \inf\{\lambda\in\mathbb{R}:\ \rho \leq 2^\lambda\sigma\},
\end{equation}
and if $\supp(\rho)\nsubseteq\supp(\sigma)$ then $D_{\max}(\rho\Vert\sigma)=\infty$.

\label{def:key-state}
A conference key state $\gamma^c_{\vv{K}E}$, with $|K_i|=K$ for all $i\in[M]\coloneqq\{1,…,M\}$, is defined as 
\begin{align}
& \mathcal{D}_{K_1}\otimes\mathcal{D}_{K_2}\otimes\cdots\otimes \mathcal{D}_{K_M}\left(\gamma^c_{\vv{K} E}\right) \coloneqq \nonumber \\ 
&\qquad \frac{1}{K}\sum_{k\in\msc{K}}\op{k}_{K_1}\otimes \op{k}_{K_2}\otimes\cdots \otimes \op{k}_{K_M}\otimes\sigma_E, \label{eq:key-state}
\end{align}
where $\sigma_E$ is a state of the system $E$, which is accessible to an eavesdropper Eve, $\mathcal{D}(\cdot)=\sum_{k\in\msc{K}}\op{k}(\cdot)\op{k}$ is a projective measurement channel, $\{\ket{k}_{K_i}\}_{k\in\msc{K}}$ forms an orthonormal basis for each $i\in[M]$.

\label{def:multi-priv-state}
A state $\gamma_{\vv{SM}}$, with $|K_i|=K$ for all $i\in[M]$ is called a ($M$-partite) private state if and only if 
\begin{equation}\label{eq:multi-priv-state}
\gamma_{\vv{SK}}\coloneqq U^{\text{tw}}_{\vv{SK}} (\Phi^{\GHZ}_{\vv{K}}\otimes\omega_{\vv{S}}) (U^{\text{tw}}_{\vv{SK}})^\dag,
\end{equation}
where $U^{\text{tw}}_{\vv{SK}}\coloneqq \sum_{\vv{k}\in\msc{K}^{\times M}}\op{\vv{k}}_{\vv{K}}\otimes U^{\vv{k}}_{\vv{S}}$ is called a twisting unitary operator for some unitary operator $U^{\vv{k}}_{\vv{S}}$ and $\omega$ is some density operator~\cite{AH09}.

\label{def:gen-div-ent}
The generalized divergence of entanglement $\tf{E}_{\text{E}}$ or genuine mulipartite entanglement (GME) $\tf{E}_\text{GE}$ of an arbitrary state $\rho_{\vv{A}}$ is defined as~\cite{CPV19}
\begin{equation}\label{eq:def-gen-ent}
\tf{E}_{r}(:\!\vv{A}\!:)_{\rho}\coloneqq \inf_{\sigma\in\tf{F}(:\!\vv{A}\!:)}\tf{D}(\rho_{\vv{A}}\Vert\sigma_{\vv{A}}),
\end{equation} 
when $\tf{F}=\FS$ or $\tf{F}=\BS$ for $r=\text{E}$ or $r=\text{GE}$, respectively, where $\tf{D}(\rho\Vert\sigma)$ denotes the generalized divergence.

Entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to entanglement measure $\tf{E}_{r}$ [Eq. ~\eqref{eq:def-gen-ent}] is defined as the maximum possible gain in the entanglement $\tf{E}_r$ when a quantum state when acted upon by the given channel $\mc{N}$, 
\begin{align}
&\tf{E}_{r}^{p}(\mc{N})\coloneqq\nonumber\\
&\qquad \sup_{\rho}\left[\tf{E}_{r}(:\!\vv{LA}\!:\!\vv{R}\!:\!\vv{PC}\!:)_{\mc{N}(\rho)} -\tf{E}_{r}(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)_{\rho}\right],
\end{align}
where optimization is over all possible input states $\rho_{\vv{LA'}\vv{RB}\vv{P}}$.

A multipartite quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is teleportation-simulable with associated resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$, where $R_b\simeq B_b$ for all $b\in\msc{B}$ and $L_a\simeq A'_a$ for all $a\in\msc{A}$, if for all input states $\rho_{\vv{A'}\vv{B}}$ the following identity holds
\begin{equation}\label{eq:tele-sim}
\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}})=\mc{T}_{\vv{A'LA}\vv{BR}\vv{C}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}}\otimes\theta_{\vv{LA}\vv{R}\vv{C}})

\end{equation} 
for some LOCC channel $\mc{T}$ with input partition $:\vv{A'LA}:\vv{BR}:\vv{C}:$ and output partition $:\vv{A}:\vv{C}:$.

theorem.raw:
\label{thm:priv-gme}
A biseparable state $\sigma_{\vv{SK}}\in\BS(:\!\vv{SK}\!:)$ can never pass any $\gamma$-privacy test with probability greater $1/K$, i.e.,
\begin{align}
    \Tr[\Pi^{\gamma}_{\vv{SK}}\sigma_{\vv{SK}}]\leq \frac{1}{K}.
\end{align}

\label{thm:one-shot-cppp}
For any fixed $\varepsilon\in(0,1)$, the achievable region of cppp-assisted secret key agreement over a single use of multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ satisfies 
\begin{equation}\label{eq:one-shot-cppp}
\hat{P}_{\textnormal{cppp}}^{\mc{N}}(1,\varepsilon)\leq E^\varepsilon_{h,\GE}(\mc{N}),
\end{equation} 
where 
\begin{equation}
E^{\varepsilon}_{h,\GE}(\mc{N})  \coloneqq \sup_{\psi\in\FS(:\vv{LA'}:\vv{RB}:)}\inf_{\sigma\in\BS(:\vv{LA}:\vv{R}:\vv{C}:)} D^\varepsilon_h(\mc{N}(\psi)\Vert\sigma)
\end{equation}
is the $\varepsilon$-hypothesis testing relative entropy of genuine entanglement of the multiplex channel $\mc{N}$. It suffices to optimize over pure input states $\psi\in\FS(:\!\vv{LA'}\!:\!\vv{RB}\!:)$.

\label{thm:emax-key-converse} For a fixed $n,\ K\in\mathbb{N},\ \varepsilon\in(0,1)$, the following bound holds for an $(n,K,\varepsilon)$ protocol for LOCC-assisted secret key agreement over a multiplex $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$: 
\begin{equation}\label{eq:emax-key-converse} 
\frac{1}{n}\log_2K\leq E_{\max,E}(\mc{N})+ \frac{1}{n}\log_2\left(\frac{1}{1-\varepsilon}\right), 
\end{equation} 
where the max-relative entropy of entanglement $E_{\max,\E}(\mc{N})$ of the multiplex channel $\mc{N}$ is 
\begin{equation*} 
E_{\max,\E}(\mc{N}) \coloneqq \sup_{\psi\in\FS(:\vv{LA'}:\vv{RB}:)}\inf_{\sigma\in\FS(:\vv{LA}:\vv{R}:\vv{C}:)} D_{\max}(\mc{N}(\psi)\Vert\sigma)
\end{equation*} 
and it suffices to optimize over pure states $\psi$.

\label{thm:ree-key-converse}  
For finite Hilbert space dimensions the asymptotic LOCC-assisted secret-key-agreement capacity of a  multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is bounded by its regularized relative entropy of entanglement:
\begin{equation}\label{eq:ree-key-converse} 
\widetilde{\mc{P}}_{\LOCC}(\mc{N})\leq E_{E}^\infty(\mc{N}).
\end{equation}

\label{thm:bicov}
If a multipartite channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$
is tele-covariant, then it is teleportation-simulable with resource state~\eqref{eq:tele-sim} as its Choi state, i.e., $\theta_{\vv{LA}\vv{R}\vv{C}}=\mc{N}(\Phi^+_{\vv{L}\vv{R}|\vv{A'}\vv{B}})$.

\label{theo:telecov-weakconv-GE}
The LOCC-assisted secret-key-agreement capacity of a multiplex quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ which is teleportation-simulable with resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$ is upper bounded as 
\begin{equation}
\hat{P}_{\LOCC}(\mc{N})\leq E^{\infty}_{GE}(:\vv{LA}:\vv{R}:\vv{C}:)_{\theta}, 
\end{equation}
where $E^\infty(:\vv{A}:)_{\rho}$ is the regularized relative entropy of entanglement of state $\rho_{\vv{A}}$.

\label{theo:E-alpha_bound}
For a fixed $n,\ K\in\mathbb{N},\ \varepsilon\in(0,1)$, the following bound holds for an $(n,M,\varepsilon)$ protocol for LOCC-assisted secret key agreement over a multiplex teleportation-simulable quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with associated resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$,  $\forall \alpha>1$,
\begin{equation}\label{eq:GE-tele-weak-converse}
\frac{1}{n} \log_2 K \leq  \widetilde{E}_{\alpha,E} (:\vv{LA}:\vv{R}:\vv{C}:)_{\theta} 
+\frac{\alpha}{n(\alpha-1)}\log_2 \!\(
\frac{1}{1-\varepsilon}\).
\end{equation}

\label{cor:states}
    For any fixed $\varepsilon\in (0,1)$, the achievable region of secret key agreement from a single copy of an arbitrary multipartite quantum state $\rho_{\vv{A}}$ satisfies 
    \begin{equation}\label{eqn:advanatge1}
        K_{\textnormal{D}}^{(1,\varepsilon)}(\rho)\leq E^\varepsilon_{h,\GE}(:\vv{A}:)_{\rho},
    \end{equation} 
    where 
    \begin{equation}\label{eqn:advanatge2}
        E^{\varepsilon}_{h,\GE}(:\vv{A}:)_{\rho}\coloneqq \inf_{\sigma\in\BS(:\vv{A}:)} D^\varepsilon_h(\rho\Vert\sigma).
    \end{equation}
    is the $\varepsilon$-hypothesis testing relative entropy of genuine entanglement of multipartite state $\rho_{\vv{A}}$.

lemma.raw:
\label{lem:fid-hyp}
The following relation holds between the hypothesis testing relative entropy and fidelity between two states $\rho,\sigma$:
\begin{align}
   &D^\varepsilon_h(\rho,\sigma) \nonumber \\
&\leq -2 \log_2 \left(\sqrt{F}(\rho,\sigma) - \sqrt{\varepsilon}\sqrt{1-\left(\sqrt{F}(\rho,\sigma)- \sqrt{\varepsilon}\right)^2}\right) \\ 
&\leq -2 \log_2 \left(\sqrt{F}(\rho,\sigma) - \sqrt{\varepsilon} \right),
\end{align}
for a fixed $\varepsilon\in[0,\sqrt{F}(\rho,\sigma))$.

\label{lem:TD-hyp}The following relation holds between the hypothesis testing relative entropy and the trace distance between any two states $\rho,\sigma$:
\begin{equation}\label{eqn:TD-hyp0}
	D^{\varepsilon}_h(\rho\Vert\sigma)\leq -\log_2 \left(1 - \frac 12 \norm{\rho - \sigma}_1 - \varepsilon \right).
\end{equation}
for a fixed $\varepsilon\in[0,1-\frac 12 \norm{\rho - \sigma}_1)$,

\label{lem:exactD} If $\rho$ is pure and it is one of the eigenvectors of $\sigma$ , i.e., there exists decomposition $\sigma = p_0 \rho + \sum_{i=1} p_i \gamma_i^\perp$, with $\sum_{i=0}p_i=1$, $0\le p_i \le 1$, $p_0 \neq 0$ and states $\gamma_i^\perp$ orthogonal to $\rho$ then for any $\epsilon \in [0,1]$:
\begin{align}
	D_h^\varepsilon \left(\rho \Vert \sigma  \right) = -\log_2 \Tr \left[\Omega \sigma\right],
\end{align}
with $\Omega = (1-\varepsilon)\rho$.

\label{lem:max-amor}
The entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to the max-relative entropy of entanglement $E_{\max,\E}$ is equal to the max-relative entropy of entanglement of the channel $\mc{N}$,
\begin{equation}
E_{\max,E}^{p}(\mc{N})=E_{\max,E}(\mc{N}).\label{eq:max-amor}
\end{equation}

\label{lem:ree-amor}
For finite dimensional Hilbert spaces the entangling power of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ with respect to the relative entropy of entanglement $E_{E}$ is less than or equal to the regularized relative entropy of entanglement of the channel $\mc{N}$,
\begin{equation}
E_{E}^{p}(\mc{N})\leq E^\infty_{E}(\mc{N}).
\end{equation}

\label{lem:exactD} If $\rho$ is a pure state and it is one of the eigenvectors of $\sigma$ , i.e., there exists decomposition $\sigma = p_0 \rho + \sum_{i=1} p_i \gamma_i^\perp$, with $\sum_{i=0}p_i=1$, $0\le p_i \le 1$, $p_0 \neq 0$ and states $\gamma_i^\perp$ orthogonal to $\rho$ then for any $\epsilon \in [0,1]$:
\begin{align}
	D_h^\varepsilon \left(\rho \Vert \sigma  \right) = -\log_2 \Tr \left[\Omega \sigma\right],
\end{align}
with $\Omega = (1-\varepsilon)\rho$.

\label{bisep:lemma7}
Let $\mc{T}=\{{U^{tw}}^\dagger\rho_{\vv{SK}}U^{tw}:\rho_{\vv{SK}}\in \BS(:\vv{SK}:)\}$ be the set of twisted biseparable states. Then for any $\sigma_{\vv{SK}}\in\mc{T}$ it holds
\begin{equation}
D(\Phi_{\vv{K}}||\sigma_{\vv{K}})\geq\log{K}.
\end{equation}

proposition.raw:
\label{thm:priv-test}
If a state $\rho_{\vv{SK}}$ is $\varepsilon$-approximate to $\gamma_{\vv{SK}}$, i.e., $F(\rho_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon$ then $\rho_{\vv{KS}}$ passes $\gamma$-privacy test with success probability $ 1-\varepsilon$, i.e., 
\begin{equation}
\Tr[\Pi^{\gamma}_{\vv{SK}}\rho_{\vv{SK}}] \geq 1-\varepsilon.
\end{equation}

\label{bisep:theorem9}
For an $m$-partite state $\rho_{\vv{A}}$ it holds that
\begin{equation}
K_D(\rho_{\vv{A}})\leq E^\infty_{GE}(\rho_{\vv{A}}).
\end{equation}

corollary.raw:
A weak converse bound on the cppp-assisted secret-key-agreement capacity of a multiplex channel $\mc{N}$ is given by
\begin{align}
    \hat{P}_{\textnormal{cppp}}(\mc{N})& = \inf_{\varepsilon\in (0,1)}\liminf_{n\to\infty}\hat{P}^{\mc{N}}_{\textnormal{cppp}}(n,\varepsilon)\\ 
    &\leq E^{\infty}_{\GE}(\mc{N}).
\end{align}

The strong converse LOCC-assisted secret-key-agreement capacity of a multiplex channel $\mc{N}$ is bounded from above by its max-relative entropy of entanglement:
\begin{equation}
\wt{P}_{\LOCC}(\mc{N})\leq E_{\max,E}(\mc{N}).
\end{equation}

\label{thm:tele}
The LOCC-assisted secret-key-agreement capacity of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ which is teleportation-simulable with resource state $\theta_{\vv{LA}\vv{R}\vv{C}}$ is upper bounded as 
\begin{equation}\label{eq:tele-bound}
\hat{P}_{\LOCC}(\mc{N})\leq E_E(:\vv{LA}:\vv{R}:\vv{C}:)_{\theta}, 
\end{equation}
where $E(:\vv{A}:)_{\rho}$ is the relative entropy of entanglement of state $\rho_{\vv{A}}$; this bound is also a strong converse bound.

\label{cor:dist-state}
For any $M$-partite state  $\rho_{[M]}$ defined on the Hilbert space ${\mathcal H}$, the asymptotic secret-key-agreement rate satisfies the following inequality:
\begin{align}
    \max_L K_D(\rho_{[L]})\leq K_D(\rho_{[M]}) \leq \min_{N} K_D(\rho_{[N]}),
\end{align}
where the state $\rho_{[L]}$ is 
obtained from the state $\rho_{[M]}$ by splitting its subsystems so that $L\geq \log \dim({\mathcal H})$.
Analogously the state $\rho_{[N]}$ is obtained via any merging of subsystems of $\rho_{[M]}$, such that $\rho_{[N]}$ has at least two subsystems.

proof.raw:
Let $\rho_{\vv{LA'}\vv{RB}\vv{P}}$ be a state and let $\sigma'\in\FS(:\vv{LA'}:\vv{RB}:\vv{P}:)$ and $\sigma\in\FS(:\vv{LA}:\vv{R}:\vv{PC}:)$. Then the following inequality holds
\begin{multline}
 E_{\max,E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\ 
 \leq D_{\max}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}\).
 \end{multline}
Applying the data-processed triangle inequality \cite[Theorem III.1]{CM17}, we find that
\begin{multline}
D_{\max}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}\)\\
 \leq D_{\max}(\rho_{\vv{LA'}\vv{RB}\vv{P}}\Vert\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \\ 
 +D_{\max}(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}).
\end{multline}
Since $\sigma'_{\vv{LA'}\vv{RB}\vv{P}}$ and $\sigma_{\vv{LA}\vv{R}\vv{PC}}$ are arbitrary fully separable states, we arrive at
\begin{multline}
E_{\max,E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}
 \leq  E_{\max,E}(:\vv{LA'}:\vv{RB}:\vv{P}:)_{\rho}\\
 + E_{\max,E}(L:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\sigma')}.
\end{multline}
This implies that $E_{\max,E}^{p}(\mc{N})\leq E_{\max,E}(\mc{N})$ given that $\sigma'\in\FS(:\vv{LA'}:\vv{RB}:\vv{P}:)$. Notice that $E_{\max,E}^{p}(\mc{N})\geq E_{\max,E}(\mc{N})$ always holds. Hence, Eq.~\eqref{eq:max-amor} holds.

Let $\rho_{\vv{LA'}\vv{RB}\vv{P}}$ be a state and let $\sigma'\in\FS(:\vv{LA'}:\vv{RB}:\vv{P}:)$. Let $\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ an LOCC channel. Then the following inequality holds
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\ 
 \leq D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \).
 \end{multline}
Applying the the chain rule from Ref.~\cite{fang2019chain}, we find that
\begin{align*}
&D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \)\\
\leq&D\(\rho_{\vv{LA'}\vv{RB}\vv{P}}\Vert \sigma'_{\vv{LA'}\vv{RB}\vv{P}} \)\\ 
& +D^{\infty}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\).
\end{align*}
Since the above holds for arbitrary fully separable states $\sigma'_{\vv{LA'}\vv{RB}\vv{P}}$ and arbitrary LOCC channels $\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, we arrive at
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\
 \leq  E_{E}(:\vv{LA'}:\vv{RB}:\vv{P}:)_{\rho}+ E^\infty_{E}(\mc{N}),
\end{multline}
finishing the proof.

Let us consider any cppp-assisted protocol that achieves a rate $\hat{P}_{\textnormal{cppp}}^{\mc{N}}\equiv \hat{P}$. Let $\rho^{(1)}\in\FS(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)$ be a fully separable state generated by the first use of LOCC among all spatially separated allies. Let 
\begin{equation}
\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}\coloneqq \mc{N}(\rho^{(1)}_{\vv{LA}\vv{RB}\vv{P}}).
\end{equation}  
We note that for $\tau^{(1)}$ is a separable state with respect to bipartition $\vv{LA}\vv{R}\vv{C}\!:\!\vv{P}$. The action of the decoder channel $\mc{D}\coloneqq \mc{L}^{(2)}_{\vv{LA}\vv{R}\vv{PC}\to \vv{SK}}$ on $\tau^{(1)}$ yields the state
\begin{equation}
\omega_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}).
\end{equation}
By assumption we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some ($M$-partite) private state $\gamma$. This implies that there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
From Theorem~\ref{thm:priv-gme},
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\sigma'_{\vv{SK}}]\leq \frac{1}{K}=2^{-\hat{P}},
\end{equation}
for any $\sigma'\in\BS(:\!\vv{SK}\!:)$. 

Let us suppose a state $\sigma_{\vv{LA}\vv{R}\vv{PC}}\in\BS(:\vv{LA}:\vv{R}:\vv{PC}:)$ of the form $\sigma_{\vv{LA}\vv{R}\vv{PC}}=\sigma_{\vv{LA}\vv{R}\vv{C}}\otimes\sigma_{\vv{P}}$, where $\sigma{\vv{LA}\vv{R}\vv{C}}$ is arbitrary. It holds that $\sigma_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\sigma_{\vv{LA}\vv{R}\vv{PC}})\in\BS(:\vv{SK}:)$. Thus, the privacy test is feasible for $D^\varepsilon_h(\omega\Vert \sigma)$ and we find that
\begin{align}
\hat{P} &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}})\\
&\leq  D^\varepsilon_h(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}} )\label{eq:40}\\
&\leq \sup_{\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}:\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}})\\
&= \sup_{\psi\in\FS(\vv{LA'}:\vv{RB})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}})\Vert \sigma_{\vv{LA}\vv{R}\vv{C}}).\label{eq:one-shot-proof-part}
\end{align}

The second inequality follows from data processing inequality. The third inequality follows from the quasi-convexity of $D^\varepsilon_h$. The equality follows from Eq.~\eqref{eq:gen-div-prod} and suitable choice of $\sigma_{\vv{P}}$ that always exists because for any pure state $\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})$, the output state $\mc{N}(\psi)$ is separable with respect to bipartition $\vv{LA}\vv{R}\vv{C}:\vv{P}$. 

Since inequality \eqref{eq:one-shot-proof-part} also holds for an arbitrary $\sigma\in\BS(:\!\vv{LA}\!:\!\vv{R}\!:\vv{C}\!:)$, we can conclude that
\begin{equation}
\hat{P}\leq E^\varepsilon_{h,\GE}(\mc{N}).
\end{equation}

The following inequality holds for an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$:
\begin{equation}\label{eq:fid-conv-proof}
F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon. 
\end{equation}
For any $\sigma_{\vv{SK}}\in\FS(:\vv{SK}:)$, we have following bound due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme}:
\begin{equation}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Employing inequality \eqref{eq:hyp-sand-rel} in the limit $\alpha\to+\infty$, we obtain
\begin{align}
\log_2 K &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \\
&\leq D_{\max}(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{align}
Above inequality holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, therefore
\begin{equation}\label{eq:con-max-proof}
\log_2 K \leq E_{\max,\E}(:\vv{SK}:)_{\omega}+\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $E_{\max,\E}(:\vv{SK}:)_{\omega}$ is the max-relative entropy of entanglement of the state $\omega_{\vv{SK}}$.

The max-relative entropy of entanglement $E_{\max,\E}$ of a state is monotonically non-increasing under the action of LOCC channels and it is zero for states that are fully separable. Using these facts, we get that
\begin{align}
& E_{\max,\E}(:\vv{SK}:)_{\omega}\nonumber \\
&\leq E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \label{eq:52}\\
&=  E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_1}\\ 
&=E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\ 
&\qquad +\left[\sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right.\nonumber \\
&\qquad  -\left. \sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\nonumber \\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}\\
& \leq \sum_{i=1}^n \left[ E_{\max,\E}(:\vv{L^{(i)}A^{(i)}}:\vv{R^{(i)}}:\vv{P^{(i)}C^{(i)}}:)_{\tau_{i}} \right. \nonumber\\
&\qquad -\left.  E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\\
&\leq n E_{\max,\E}(\mc{N}).\label{eq:amor-proof}
\end{align}
The first equality follows because $E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}=0$. The second inequality follows because $E_{\max,\GE}$ is monotone under LOCC channels and $\rho_{i}=\mc{L}^{i}(\tau_{i-1})$ for all $i\in\{2,3,\ldots,n\}$. The final inequality follows from Lemma~\ref{lem:max-amor}.

From inequalities \eqref{eq:con-max-proof} and \eqref{eq:amor-proof}, we conclude that
\begin{equation}
\log_2K\leq nE_{\max,\E}(\mc{N})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{equation}

For an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$, such that $F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon$, due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme} it holds for any $\sigma_{\vv{SK}}\in\FS(:\vv{SK}:)$:
\begin{equation}\label{eq:68}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Using the fact that~\cite{WR12}
\begin{equation}
D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \leq \frac{1}{1-\varepsilon}\(D(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+h(\varepsilon)\),
\end{equation}
where $h$ is the binary entropy function, and that the bound~\eqref{eq:68} holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, we obtain
\begin{equation}\label{eq:con-ree-proof-1}
\log_2 K \leq \frac{1}{1-\varepsilon}\(E_{\E}(:\vv{SK}:)_{\omega}+h(\varepsilon)\)\end{equation}
As the relative entropy of entanglement of a state is monotonically non-increasing under the action of LOCC channels and vanishes for states that are fully separable we can repeat the argument in inequalities~\eqref{eq:52}--\eqref{eq:amor-proof} and obtain
\begin{equation}\label{eq:amor-proof_ree}
E_{\E}(:\vv{SK}:)_{\omega}\leq n E^p_{\E}(\mc{N})\leq n E^\infty_{\E}(\mc{N}),
\end{equation}
where the second inequality follows from Lemma~\ref{lem:ree-amor}, Taking the limits $\varepsilon\to0$ and $n\to\infty$, we obtain \begin{equation}
\hat{\mc{P}}_{\LOCC}(\mc{N})\leq E^\infty_{\E}(\mc{N}),
\end{equation}
showing the converse. As for the strong converse, we follow the argument used in Ref.~\cite{WTB16}: From inequalities~\eqref{eq:68} and  \eqref{eq:hyp-sand-rel} we obtain
\begin{equation}\label{eq:con-ree-proof}
\log_2 K \leq \widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}+\frac{\alpha}{\alpha-1}\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $\alpha\in(1,\infty)$ and $\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}$ is the sandwiched R\'{e}nyi relative entropy of entanglement of the state $\omega_{\vv{SK}}$. Rewriting inequality~\eqref{eq:con-ree-proof} we obtain
\begin{equation}
\varepsilon\geq 1- 2^{-n\(\frac{\alpha-1}{\alpha}\)\(\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}\)}.
\end{equation}
Assuming that the rate $\frac{\log_2 K}{n}$ exceeds $E_{E}^\infty(\mc{N})$, by inequality~\eqref{eq:amor-proof_ree} it will be larger than $\frac{1}{n}E_{\E}(:\vv{SK}:)_{\omega}$. Hence, there exists an $\alpha>1$, such that $\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}>0$ and the error increases to $1$ exponentially.

We begin by showing the bound for pure biseparable states $\ket{\varphi}_{\vv{KS}}$. For such a state there exists a bipartition of the parties, defined by nonempty index sets $I\subset\{1,...,M\}$ and $J=\{1,...,M\}\setminus I$, such that the state is product with respect to that bipartition.  Namely $\ket{\varphi}_{\vv{KS}}=\ket{\widetilde\varphi}_{S_{I}K_{I}}\otimes\ket{\overline\varphi}_{S_{J}K_{J}}$, where we have defined $\mc{H}_{S_{I}K_{I}}=\bigotimes_{i\in I}\mc{H}_{S_{i}K_{i}}$ and $\mc{H}_{S_{J}K_{J}}=\bigotimes_{j\in J}\mc{H}_{S_{j}K_{j}}$.
Let us also define $m:=|I|$ and $n:=|J|$ and note that $M=m+n$. We can expand
\begin{align}
&\ket{\widetilde\varphi}_{S_{I}K_{I}}=\sum_{i_1,...,i_{m}=0}^{K-1}\widetilde{\alpha}_{i_1...i_{m}}\ket{i_1...i_{m}}_{K_{I}}\otimes\ket{\widetilde{\phi}_{i_1...i_{m}}}_{S_{I}}\\
&\ket{\overline\varphi}_{S_{J}K_{J}}=\sum_{j_1,...,j_{n}=0}^{K-1}\overline{\alpha}_{j_1...j_{n}}\ket{j_1...j_{n}}_{K_J}\otimes\ket{\overline{\phi}_{j_1...j_{n}}}_{S_J}.
\end{align}
Here $\widetilde{\alpha}_{i_1...i_{m}}\in\bbm{C}$ such that $\sum_{i_1,...,i_{m}=0}^{K-1}|\widetilde{\alpha}_{i_1...i_{m}}|^2=1$ and $\overline{\alpha}_{j_1...j_{n}}\in\bbm{C}$ such that $\sum_{j_1,...,j_{n}=0}^{K-1}|\overline{\alpha}_{j_1...j_{n}}|^2=1$. Further it holds

\begin{widetext}
\begin{align}
\Tr\left[\Pi^{\gamma,K}_{\vv{KS}}\varphi_{\vv{KS}}\right]
&=\Tr\left[\(\frac{1}{K}\sum_{i,k=0}^{K-1}\(\ket{i}\bra{k}\)^{\otimes M}_{\vv{K}}\otimes U_{\vv{S}}^{(i^M)}U_{\vv{S}}^{(k^M)\dag}\)\widetilde\varphi_{K_IS_I}\otimes\overline\varphi_{K_JS_J}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^{m}}\overline{\alpha}_{i^{n}}(\widetilde{\alpha}_{k^{m}})^*(\overline{\alpha}_{k^{n}})^*\Tr\left[U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}\bra{\widetilde{\phi}_{k^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}\bra{\overline{\phi}_{k^n}}_{S_J}U^{(k^M)}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i},\label{eq:9}
\end{align}
\end{widetext}
where we have defined the state
\begin{equation}
\ket{\zeta_i}_{\vv{S}} \coloneqq U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}_{S_J}.
\end{equation}
We note that eq. (\ref{eq:9}) is a probability, in particular it is real and non-negative. Hence it holds
\begin{align}
&\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i}\\
&=\left|\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i}\right|\\
&\leq\frac{1}{K}\sum_{i,k=0}^{K-1}\left|\widetilde{\alpha}_{i^m}\right|\left|\overline{\alpha}_{i^n}\right|\left|\widetilde{\alpha}_{k^m}\right|\left|\overline{\alpha}_{k^n}\right|\left|\bra{\zeta_k}\ket{\zeta_i}\right|
\end{align}
where in the first inequality we have used the subadditivity and multiplicity of the absolute value of complex numbers. We note that for all $i,k$ in the sum $\left|\bra{\zeta_k}\ket{\zeta_i}\right|\leq 1$. Let us define $p_i=\left|\widetilde{\alpha}_{i^m}\right|^2$ and note that $p_i\geq0$ and $\sum_{i=0}^{K-1}p_i\leq1$. Let us also define $q_i=\left|\overline{\alpha}_{i^n}\right|^2$ and note that $q_i\geq0$ and $\sum_{i=0}^{K-1}q_i\leq1$. Hence there exist respective probability distributions $\{\hat{p}_i\}$ and $\{\hat{q}_i\}$ over $\{0,...,K-1\}$ such that $p_i\leq\hat{p}_i$ and $q_i\leq\hat{q}_i$ for all $i=0,...,K-1$. We then obtain
\begin{align}
&\frac{1}{K}\sum_{i,k=0}^{K-1}\left|\widetilde{\alpha}_{i^m}\right|\left|\overline{\alpha}_{i^n}\right|\left|\widetilde{\alpha}_{k^m}\right|\left|\overline{\alpha}_{k^n}\right|\left|\bra{\zeta_k}\ket{\zeta_i}\right|\\
&\leq\frac{1}{K}\sum_{i,k=0}^{K-1}\sqrt{p_iq_ip_kq_k} =\frac{1}{K}\left[\sum_{i=0}^{K-1}\sqrt{p_iq_i}\right]^2\\
&\leq\frac{1}{K}\left[\sum_{i=0}^{K-1}\sqrt{\hat{p}_i\hat{q}_i}\right]^2\leq\frac{1}{K},
\end{align}
where we have used that the classical fidelity between two probability distributions is upper bounded by $1$. This establishes the theorem for pure biseparable states with respect to arbitrary bipartitions. Noting that every mixed biseparable state $\sigma_{\vv{KS}}\in\BS(:\vv{KS}:)$ can be expressed as a convex sum of pure biseparable states finishes the proof.

Let us consider any cppp-assisted protocol that achieves a rate $\hat{P}_{\textnormal{cppp}}^{\mc{N}}\equiv \hat{P}$. Let $\rho^{(1)}\in\FS(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)$ be a fully separable state generated by the first use of LOCC among all spatially separated allies. Let 
\begin{equation}
\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}\coloneqq \mc{N}(\rho^{(1)}_{\vv{LA}\vv{RB}\vv{P}}).
\end{equation}  
We note that $\tau^{(1)}$ is a separable state with respect to bipartition $\vv{LA}\vv{R}\vv{C}\!:\!\vv{P}$. The action of the decoder channel $\mc{D}\coloneqq \mc{L}^{(2)}_{\vv{LA}\vv{R}\vv{PC}\to \vv{SK}}$ on $\tau^{(1)}$ yields the state
\begin{equation}
\omega_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}).
\end{equation}
By assumption we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some ($M$-partite) private state $\gamma$. This implies that there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
From Theorem~\ref{thm:priv-gme},
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\sigma'_{\vv{SK}}]\leq \frac{1}{K}=2^{-\hat{P}},
\end{equation}
for any $\sigma'\in\BS(:\!\vv{SK}\!:)$. 

Let us suppose a state $\sigma_{\vv{LA}\vv{R}\vv{PC}}\in\BS(:\vv{LA}:\vv{R}:\vv{PC}:)$ of the form $\sigma_{\vv{LA}\vv{R}\vv{PC}}=\sigma_{\vv{LA}\vv{R}\vv{C}}\otimes\sigma_{\vv{P}}$, where $\sigma{\vv{LA}\vv{R}\vv{C}}$ is arbitrary. It holds that $\sigma_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\sigma_{\vv{LA}\vv{R}\vv{PC}})\in\BS(:\vv{SK}:)$. Thus, the privacy test is feasible for $D^\varepsilon_h(\omega\Vert \sigma)$ and we find that
\begin{align}
\hat{P} &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}})\\
&\leq  D^\varepsilon_h(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}} )\label{eq:40}\\
&\leq \sup_{\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}:\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}})\\
&= \sup_{\psi\in\FS(\vv{LA'}:\vv{RB})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}})\Vert \sigma_{\vv{LA}\vv{R}\vv{C}}).\label{eq:one-shot-proof-part}
\end{align}

The second inequality follows from data processing inequality. The third inequality follows from the quasi-convexity of $D^\varepsilon_h$. The equality follows from Eq.~\eqref{eq:gen-div-prod} and suitable choice of $\sigma_{\vv{P}}$ that always exists because for any pure state $\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})$, the output state $\mc{N}(\psi)$ is separable with respect to bipartition $\vv{LA}\vv{R}\vv{C}:\vv{P}$. 

Since inequality \eqref{eq:one-shot-proof-part} also holds for an arbitrary $\sigma\in\BS(:\!\vv{LA}\!:\!\vv{R}\!:\vv{C}\!:)$, we can conclude that
\begin{equation}
\hat{P}\leq E^\varepsilon_{h,\GE}(\mc{N}).
\end{equation}

The following inequality holds for an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$:
\begin{equation}\label{eq:fid-conv-proof}
F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon. 
\end{equation}
For any $\sigma_{\vv{SK}}\in\FS(:\vv{SK}:)$, we have following bound due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme}:
\begin{equation}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Employing inequality \eqref{eq:hyp-sand-rel} in the limit $\alpha\to+\infty$, we obtain
\begin{align}
\log_2 K &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \\
&\leq D_{\max}(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{align}
Above inequality holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, therefore
\begin{equation}\label{eq:con-max-proof}
\log_2 K \leq E_{\max,\E}(:\vv{SK}:)_{\omega}+\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $E_{\max,\E}(:\vv{SK}:)_{\omega}$ is the max-relative entropy of entanglement of the state $\omega_{\vv{SK}}$.

The max-relative entropy of entanglement $E_{\max,\E}$ of a state is monotonically non-increasing under the action of LOCC channels and it is zero for states that are fully separable. Using these facts, we get that
\begin{align}
& E_{\max,\E}(:\vv{SK}:)_{\omega}\nonumber \\
&\leq E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \label{eq:52}\\
&=  E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_1}\\ 
&=E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\ 
&\qquad +\left[\sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right.\nonumber \\
&\qquad  -\left. \sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\nonumber \\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}\\
& \leq \sum_{i=1}^n \left[ E_{\max,\E}(:\vv{L^{(i)}A^{(i)}}:\vv{R^{(i)}}:\vv{P^{(i)}C^{(i)}}:)_{\tau_{i}} \right. \nonumber\\
&\qquad -\left.  E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\\
&\leq n E_{\max,\E}(\mc{N}).\label{eq:amor-proof}
\end{align}
The first equality follows because $E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}=0$. The second inequality follows because $E_{\max,\GE}$ is monotone under LOCC channels and $\rho_{i}=\mc{L}^{i}(\tau_{i-1})$ for all $i\in\{2,3,\ldots,n\}$. The final inequality follows from Lemma~\ref{lem:max-amor}.

From inequalities \eqref{eq:con-max-proof} and \eqref{eq:amor-proof}, we conclude that
\begin{equation}
\log_2K\leq nE_{\max,\E}(\mc{N})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{equation}

\label{app:ree-key-converse}
For an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$, such that $F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon$, due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme} it holds for any $\sigma_{\vv{SK}}\in\FS(:\vv{SK}:)$:
\begin{equation}\label{eq:68}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Using the fact that~\cite{WR12}
\begin{equation}
D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \leq \frac{1}{1-\varepsilon}\(D(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+h(\varepsilon)\),
\end{equation}
where $h$ is the binary entropy function, and that the bound~\eqref{eq:68} holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, we obtain
\begin{equation}\label{eq:con-ree-proof-1}
\log_2 K \leq \frac{1}{1-\varepsilon}\(E_{\E}(:\vv{SK}:)_{\omega}+h(\varepsilon)\)\end{equation}
As the relative entropy of entanglement of a state is monotonically non-increasing under the action of LOCC channels and vanishes for states that are fully separable we can repeat the argument in inequalities~\eqref{eq:52}--\eqref{eq:amor-proof} and obtain
\begin{equation}\label{eq:amor-proof_ree}
E_{\E}(:\vv{SK}:)_{\omega}\leq n E^p_{\E}(\mc{N})\leq n E^\infty_{\E}(\mc{N}),
\end{equation}
where the second inequality follows from Lemma~\ref{lem:ree-amor}, Taking the limits $\varepsilon\to0$ and $n\to\infty$, we obtain \begin{equation}
\hat{\mc{P}}_{\LOCC}(\mc{N})\leq E^\infty_{\E}(\mc{N}),
\end{equation}
showing the converse. As for the strong converse, we follow the argument used in Ref.~\cite{WTB16}: From inequalities~\eqref{eq:68} and  \eqref{eq:hyp-sand-rel} we obtain
\begin{equation}\label{eq:con-ree-proof}
\log_2 K \leq \widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}+\frac{\alpha}{\alpha-1}\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $\alpha\in(1,\infty)$ and $\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}$ is the sandwiched R\'{e}nyi relative entropy of entanglement of the state $\omega_{\vv{SK}}$. Rewriting inequality~\eqref{eq:con-ree-proof} we obtain
\begin{equation}
\varepsilon\geq 1- 2^{-n\(\frac{\alpha-1}{\alpha}\)\(\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}\)}.
\end{equation}
Assuming that the rate $\frac{\log_2 K}{n}$ exceeds $E_{E}^\infty(\mc{N})$, by inequality~\eqref{eq:amor-proof_ree} it will be larger than $\frac{1}{n}E_{\E}(:\vv{SK}:)_{\omega}$. Hence, there exists an $\alpha>1$, such that $\frac{\log_2 K}{n}-\frac{1}{n}\widetilde{E}_{\alpha,\E}(:\vv{SK}:)_{\omega}>0$ and the error increases to $1$ exponentially.

Let $\sigma_{\vv{SK}}\in\mc{T}$, i.e. $\sigma_{\vv{SK}}={U^{tw}}^\dagger\rho_{\vv{SK}}U^{tw}$ for some twisting unitary $U^{tw}$ and bisparable $\rho_{\vv{SK}}$. $U^{tw}$ defines a privacy test $\Pi^\gamma_{\vv{SK}}=U^{tw}(\Phi_{\vv{K}}\otimes\bbm{1}_{\vv{S}}){U^{tw}}^\dagger$. By Theorem \ref{theo:telecov-weakconv-GE}  it then holds
\begin{equation}
\Tr[\Phi_{\vv{K}}\sigma_{\vv{K}}]=\Tr[\Pi^\gamma_{\vv{SK}}\rho_{\vv{SK}}]\leq\frac{1}{K}.
\end{equation}
By the concavity of the logarithm it then holds
\begin{align}
D(\Phi_{\vv{K}}||\sigma_{\vv{K}})&=-S(\Phi_{\vv{K}})-\tr[\Phi_{\vv{K}} \log{\sigma_{\vv{K}}}]\\
&\geq-\log\Tr[\Phi_{\vv{K}}\sigma_{\vv{K}}]\\
&\geq \log K,
\end{align}
finishing the proof.

Let $\epsilon>0$ and $n\in\mathbb{N}$. We begin by noting that in the case of teleportation-simulable multiplex channels LOCC-assistance does not enhance secret-key-agreement capacity, and the original protocol can be reduced to a cppp-assisted secret key agreement protocol \cite{PLOB15}. Namely, in every round $1\leq i \leq n$ it holds 
\begin{align}
\rho_i&=\mc{L}^i(\tau_i)=\mc{L}^i(\mc{N}_{\vv{{A'}^{(i-1)}}\vv{B^{(i-1)}}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\rho_{i-1}))\\
&=\mc{L}^i(\mc{T}_{\vv{{A'}^{(i-1)}LA}\vv{B^{(i-1)}R}\vv{C}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\theta_{\vv{LA}\vv{R}\vv{C}}\otimes\rho_{i-1})),
\end{align}
where $\mc{L}^i$ and $\mc{T}$ are LOCC. As the initial state $\rho_0$ is assumed to be fully separable, we can get that the final state $\omega_{\vv{SK}}=\rho_n$ of an adaptive LOCC CKA-protocol involving $n$ uses of teleportation-simulable multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, can be expressed as
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$. 
By assumption it holds $\|\omega_{\vv{SK}}-\gamma_{\vv{KS}}\|_1\leq\epsilon$ for some $m$-partite private state $\gamma_{\vv{KS}}=U^{tw}(\Phi_{\vv{K}}\otimes\tau_{\vv{S}}){U^{tw}}^\dagger$, where $m$ is the number of parties. Let $\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}\in\BS(:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:)$. Following the proof of Theorem 9 in \cite{HHHO09}, we obtain 
\begin{align}
&D(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}||\tilde{\sigma}) \nonumber\\
&\quad \geq D(\omega_{\vv{SK}}||\mc{L}(\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}))\\
&~~~=D({U^{tw}}^\dagger\omega_{\vv{SK}}{U^{tw}}||{U^{tw}}^\dagger\mc{L}(\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}){U^{tw}})\\
&\quad \geq\inf_{\sigma_{\vv{SK}}\in\mc{T}}D(\Tr_{\vv{S}}[{U^{tw}}^\dagger\omega_{\vv{SK}}{U^{tw}}]||\sigma_{\vv{K}})\\
&\quad \geq\inf_{\sigma_{\vv{SK}}\in\mc{T}}D(\Phi_{\vv{K}}||\sigma_{\vv{K}})-4m\epsilon\log{K}-h(\epsilon)\\
&\quad \geq(1-4m\epsilon)\log{K}-h(\epsilon),
\end{align}
where in the last two inequalities we have used the asymptotic continuity of the relative entropy and Lemma \ref{bisep:lemma7}, respectively. Letting $n\to\infty$ and $\epsilon\to0$ finishes the proof.

remark.raw:
The bound in \eqref{eq:emax-key-converse} can also be rewritten as 
\begin{equation}
1-\varepsilon \leq 2^{-n (P-E_{\max,\E}(\mc{N}))},
\end{equation}
where we have $P=\frac{1}{n}\log_2 K$. Thus, if the secret-key-agreement rate $P$ is strictly greater than the max-relative entropy of entanglement $E_{\max,\E}(\mc{N})$ of the (multiplex) channel $\mc{N}$, then the fidelity of the distillation $(1-\varepsilon)$ decays exponentially fast to zero in the number of channel uses.

\label{rem:comp}
Tele-covariance of a channel is with respect to the groups and their unitary representations on the input and output Hilbert spaces of the channel. If associated unitary representations for the tele-covariant channels $\mc{N}^1$ and $\mc{N}^2$ are respectively same on the output Hilbert spaces of $\mc{N}^1$ that are also the input Hilbert spaces for $\mc{N}^2$, then the composition channel $\mc{N}=\mc{N}^2\circ\mc{N}^1$ is also tele-covariant. 

A quantum channel obtained by the tensor-product (super-operation ``~$\otimes$", which physically means parallel uses) of tele-covariant channels is also a tele-covariant channel.

