\centering
 \includegraphics[trim=4.5cm 7.5cm 4.5cm 6.5cm,width=6cm]{figure5.pdf}


        \caption{Rate-distance tradeoff comparison between our bound~\eqref{eq:dbwhh} (blue, red, yellow, purple lines) and RB bound (green line) for MDI-QKD protocol for our photon-based prototype.}\label{fig:MDI_2D} 
