Before proving Theorem \ref{theo:telecov-weakconv-GE}, we need the following lemma, which generalizes Lemma 7 in \cite{HHHO09}:
\begin{lemma}\label{bisep:lemma7}
Let $\mc{T}=\{{U^{tw}}^\dagger\rho_{\vv{SK}}U^{tw}:\rho_{\vv{SK}}\in \BS(:\vv{SK}:)\}$ be the set of twisted biseparable states. Then for any $\sigma_{\vv{SK}}\in\mc{T}$ it holds
\begin{equation}
D(\Phi_{\vv{K}}||\sigma_{\vv{K}})\geq\log{K}.
\end{equation}
\end{lemma}

\begin{proof}
Let $\sigma_{\vv{SK}}\in\mc{T}$, i.e. $\sigma_{\vv{SK}}={U^{tw}}^\dagger\rho_{\vv{SK}}U^{tw}$ for some twisting unitary $U^{tw}$ and bisparable $\rho_{\vv{SK}}$. $U^{tw}$ defines a privacy test $\Pi^\gamma_{\vv{SK}}=U^{tw}(\Phi_{\vv{K}}\otimes\bbm{1}_{\vv{S}}){U^{tw}}^\dagger$. By Theorem \ref{theo:telecov-weakconv-GE}  it then holds
\begin{equation}
\Tr[\Phi_{\vv{K}}\sigma_{\vv{K}}]=\Tr[\Pi^\gamma_{\vv{SK}}\rho_{\vv{SK}}]\leq\frac{1}{K}.
\end{equation}
By the concavity of the logarithm it then holds
\begin{align}
D(\Phi_{\vv{K}}||\sigma_{\vv{K}})&=-S(\Phi_{\vv{K}})-\tr[\Phi_{\vv{K}} \log{\sigma_{\vv{K}}}]\\
&\geq-\log\Tr[\Phi_{\vv{K}}\sigma_{\vv{K}}]\\
&\geq \log K,
\end{align}
finishing the proof.
\end{proof}

Now we can follow \cite{PLOB15} to prove Theorem \ref{theo:telecov-weakconv-GE}:

\begin{proof}[Proof of Theorem \ref{theo:telecov-weakconv-GE}]
Let $\epsilon>0$ and $n\in\mathbb{N}$. We begin by noting that in the case of teleportation-simulable multiplex channels LOCC-assistance does not enhance secret-key-agreement capacity, and the original protocol can be reduced to a cppp-assisted secret key agreement protocol \cite{PLOB15}. Namely, in every round $1\leq i \leq n$ it holds 
\begin{align}
\rho_i&=\mc{L}^i(\tau_i)=\mc{L}^i(\mc{N}_{\vv{{A'}^{(i-1)}}\vv{B^{(i-1)}}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\rho_{i-1}))\\
&=\mc{L}^i(\mc{T}_{\vv{{A'}^{(i-1)}LA}\vv{B^{(i-1)}R}\vv{C}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\theta_{\vv{LA}\vv{R}\vv{C}}\otimes\rho_{i-1})),
\end{align}
where $\mc{L}^i$ and $\mc{T}$ are LOCC. As the initial state $\rho_0$ is assumed to be fully separable, we can get that the final state $\omega_{\vv{SK}}=\rho_n$ of an adaptive LOCC CKA-protocol involving $n$ uses of teleportation-simulable multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, can be expressed as
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$. 
By assumption it holds $\|\omega_{\vv{SK}}-\gamma_{\vv{KS}}\|_1\leq\epsilon$ for some $m$-partite private state $\gamma_{\vv{KS}}=U^{tw}(\Phi_{\vv{K}}\otimes\tau_{\vv{S}}){U^{tw}}^\dagger$, where $m$ is the number of parties. Let $\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}\in\BS(:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:)$. Following the proof of Theorem 9 in \cite{HHHO09}, we obtain 
\begin{align}
&D(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}||\tilde{\sigma}) \nonumber\\
&\quad \geq D(\omega_{\vv{SK}}||\mc{L}(\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}))\\
&~~~=D({U^{tw}}^\dagger\omega_{\vv{SK}}{U^{tw}}||{U^{tw}}^\dagger\mc{L}(\tilde{\sigma}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}}){U^{tw}})\\
&\quad \geq\inf_{\sigma_{\vv{SK}}\in\mc{T}}D(\Tr_{\vv{S}}[{U^{tw}}^\dagger\omega_{\vv{SK}}{U^{tw}}]||\sigma_{\vv{K}})\\
&\quad \geq\inf_{\sigma_{\vv{SK}}\in\mc{T}}D(\Phi_{\vv{K}}||\sigma_{\vv{K}})-4m\epsilon\log{K}-h(\epsilon)\\
&\quad \geq(1-4m\epsilon)\log{K}-h(\epsilon),
\end{align}
where in the last two inequalities we have used the asymptotic continuity of the relative entropy and Lemma \ref{bisep:lemma7}, respectively. Letting $n\to\infty$ and $\epsilon\to0$ finishes the proof.


\end{proof}

}

As in the proof of Theorem \ref{theo:telecov-weakconv-GE} we have 
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$. Now following the proof of Theorem \ref{thm:one-shot-cppp}, we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some private state $\gamma$, hence there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
On the other hand, from Theorem~\ref{thm:priv-gme}, we have
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\sigma_{\vv{SK}}]\leq \frac{1}{K},
\end{equation}
for any $\sigma\in\FS(:\!\vv{SK}\!:)$. Let us suppose a state $\sigma'_{\vv{LA}\vv{R}\vv{C}}\in\FS(:\vv{LA}:\vv{R}:\vv{C}:)$ and let us define $\sigma_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\({\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)$, which is in $\FS(:\!\vv{SK}\!:)$. Hence for all $\alpha>1$ it holds,

\begin{align}
& \log_2 K\nonumber\\ 
&\leq D^\varepsilon_h\(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}}\)\\
&\leq D^\varepsilon_h\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)\\
&\leq \widetilde{D}_\alpha\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)+\frac{\alpha}{\alpha-1}\log_2\(\frac{1}{1-\epsilon}\)\\
&= n\widetilde{D}_\alpha\(\theta_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}_{\vv{LA}\vv{R}\vv{C}}\)+\frac{\alpha}{\alpha-1}\log_2\(\frac{1}{1-\epsilon}\)
\end{align}
The first inequality holds for any $\sigma\in\FS(\vv{SK})$. The second inequality follows from data processing inequality. The third inequality follows from eq. (\ref{eq:hyp-sand-rel}). The equality is due to the additivity of $\widetilde{D}_\alpha$ \cite{MDSFT13}. As the above holds for any $\sigma'_{\vv{LA}\vv{R}\vv{C}}\in\FS(:\vv{LA}:\vv{R}:\vv{C}:)$, we obtain Theorem~\ref{theo:E-alpha_bound}.

\qed

}\label{app:one-shot-cppp}
\begin{proof}
Let us consider any cppp-assisted protocol that achieves a rate $\hat{P}_{\textnormal{cppp}}^{\mc{N}}\equiv \hat{P}$. Let $\rho^{(1)}\in\FS(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)$ be a fully separable state generated by the first use of LOCC among all spatially separated allies. Let 
\begin{equation}
\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}\coloneqq \mc{N}(\rho^{(1)}_{\vv{LA}\vv{RB}\vv{P}}).
\end{equation}  
We note that $\tau^{(1)}$ is a separable state with respect to bipartition $\vv{LA}\vv{R}\vv{C}\!:\!\vv{P}$. The action of the decoder channel $\mc{D}\coloneqq \mc{L}^{(2)}_{\vv{LA}\vv{R}\vv{PC}\to \vv{SK}}$ on $\tau^{(1)}$ yields the state
\begin{equation}
\omega_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}).
\end{equation}
By assumption we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some ($M$-partite) private state $\gamma$. This implies that there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
From Theorem~\ref{thm:priv-gme},
\begin{equation}
\Tr[\Pi^\gamma_{\vv{SK}}\sigma'_{\vv{SK}}]\leq \frac{1}{K}=2^{-\hat{P}},
\end{equation}
for any $\sigma'\in\BS(:\!\vv{SK}\!:)$. 

Let us suppose a state $\sigma_{\vv{LA}\vv{R}\vv{PC}}\in\BS(:\vv{LA}:\vv{R}:\vv{PC}:)$ of the form $\sigma_{\vv{LA}\vv{R}\vv{PC}}=\sigma_{\vv{LA}\vv{R}\vv{C}}\otimes\sigma_{\vv{P}}$, where $\sigma{\vv{LA}\vv{R}\vv{C}}$ is arbitrary. It holds that $\sigma_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\sigma_{\vv{LA}\vv{R}\vv{PC}})\in\BS(:\vv{SK}:)$. Thus, the privacy test is feasible for $D^\varepsilon_h(\omega\Vert \sigma)$ and we find that
\begin{align}
\hat{P} &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}})\\
&\leq  D^\varepsilon_h(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}} )\label{eq:40}\\
&\leq \sup_{\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}:\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}})\\
&= \sup_{\psi\in\FS(\vv{LA'}:\vv{RB})}D^\varepsilon_h(\mc{N}(\psi_{\vv{LA'}:\vv{RB}})\Vert \sigma_{\vv{LA}\vv{R}\vv{C}}).\label{eq:one-shot-proof-part}
\end{align}

The second inequality follows from data processing inequality. The third inequality follows from the quasi-convexity of $D^\varepsilon_h$. The equality follows from Eq.~\eqref{eq:gen-div-prod} and suitable choice of $\sigma_{\vv{P}}$ that always exists because for any pure state $\psi\in\FS(\vv{LA'}:\vv{RB}:\vv{P})$, the output state $\mc{N}(\psi)$ is separable with respect to bipartition $\vv{LA}\vv{R}\vv{C}:\vv{P}$. 

Since inequality \eqref{eq:one-shot-proof-part} also holds for an arbitrary $\sigma\in\BS(:\!\vv{LA}\!:\!\vv{R}\!:\vv{C}\!:)$, we can conclude that
\begin{equation}
\hat{P}\leq E^\varepsilon_{h,\GE}(\mc{N}).
\end{equation} 
\end{proof}

}\label{app:emax-key-converse}
\begin{proof}
The following inequality holds for an $(n,K,\varepsilon)$ LOCC-assisted secret key agreement protocol over a multiplex channel $\mc{N}$:
\begin{equation}\label{eq:fid-conv-proof}
F(\omega_{\vv{SK}},\gamma_{\vv{SK}})\geq 1-\varepsilon. 
\end{equation}
For any $\sigma_{\vv{SK}}\in\FS(:\vv{SK}:)$, we have following bound due to inequality \eqref{eq:fid-conv-proof} and Theorem~\ref{thm:priv-gme}:
\begin{equation}
\log_2 K\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}). 
\end{equation}
Employing inequality \eqref{eq:hyp-sand-rel} in the limit $\alpha\to+\infty$, we obtain
\begin{align}
\log_2 K &\leq D^\varepsilon_h(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}}) \\
&\leq D_{\max}(\omega_{\vv{SK}}\Vert\sigma_{\vv{SK}})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{align}
Above inequality holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, therefore
\begin{equation}\label{eq:con-max-proof}
\log_2 K \leq E_{\max,\E}(:\vv{SK}:)_{\omega}+\log_2\left(\frac{1}{1-\varepsilon}\right),
\end{equation}
where $E_{\max,\E}(:\vv{SK}:)_{\omega}$ is the max-relative entropy of entanglement of the state $\omega_{\vv{SK}}$.

The max-relative entropy of entanglement $E_{\max,\E}$ of a state is monotonically non-increasing under the action of LOCC channels and it is zero for states that are fully separable. Using these facts, we get that
\begin{align}
& E_{\max,\E}(:\vv{SK}:)_{\omega}\nonumber \\
&\leq E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \label{eq:52}\\
&=  E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_1}\\ 
&=E_{\max,\E}(:\vv{L^{(n)}A^{(n)}}:\vv{R^{(n)}}:\vv{P^{(n)}C^{(n)}}:)_{\tau_n} \nonumber\\ 
&\qquad +\left[\sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right.\nonumber \\
&\qquad  -\left. \sum_{i=2}^n E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\nonumber \\
&\qquad - E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}\\
& \leq \sum_{i=1}^n \left[ E_{\max,\E}(:\vv{L^{(i)}A^{(i)}}:\vv{R^{(i)}}:\vv{P^{(i)}C^{(i)}}:)_{\tau_{i}} \right. \nonumber\\
&\qquad -\left.  E_{\max,\E}(:\vv{L^{(i)}A^{(i)'}}:\vv{R^{(i)}B^{(i)}}:\vv{P^{(i)}}:)_{\rho_{i}} \right]\\
&\leq n E_{\max,\E}(\mc{N}).\label{eq:amor-proof}
\end{align}
The first equality follows because $E_{\max,\E}(:\vv{L^{(1)}A^{(1)'}}:\vv{R^{(1)}B^{(1)}}:\vv{P^{(1)}}:)_{\rho_{1}}=0$. The second inequality follows because $E_{\max,\GE}$ is monotone under LOCC channels and $\rho_{i}=\mc{L}^{i}(\tau_{i-1})$ for all $i\in\{2,3,\ldots,n\}$. The final inequality follows from Lemma~\ref{lem:max-amor}.

From inequalities \eqref{eq:con-max-proof} and \eqref{eq:amor-proof}, we conclude that
\begin{equation}
\log_2K\leq nE_{\max,\E}(\mc{N})+\log_2\left(\frac{1}{1-\varepsilon}\right).
\end{equation}
\end{proof}

