\end{equation}
where $h$ is the binary entropy function, and that the bound~\eqref{eq:68} holds for arbitrary $\sigma\in\FS(:\vv{SK}:)$, we obtain
\begin{equation}\label{eq:con-ree-proof-1}
\log_2 K \leq \frac{1}{1-\varepsilon}\(E_{\E}(:\vv{SK}:)_{\omega}+h(\varepsilon)\)\end{equation}
As the relative entropy of entanglement of a state is monotonically non-increasing under the action of LOCC channels and vanishes for states that are fully separable we can repeat the argument in inequalities~\eqref{eq:52}--\eqref{eq:amor-proof} and obtain
\begin{equation}\label{eq:amor-proof_ree}
E_{\E}(:\vv{SK}:)_{\omega}\leq n E^p_{\E}(\mc{N})\leq n E^\infty_{\E}(\mc{N}),
\end{equation}
where the second inequality follows from Lemma~\ref{lem:ree-amor}, Taking the limits $\varepsilon\to0$ and $n\to\infty$, we obtain \begin{equation}
\hat{\mc{P}}_{\LOCC}(\mc{N})\leq E^\infty_{\E}(\mc{N}),
\end{equation}
